"/ppdb": "<div id=\"menu-ppdb\" class=\"absolute top-full left-0 w-72 animate-[munculKabar_0.15s_ease-out] pt-2\"><ul class=\"overflow-hidden rounded-kartu border border-garis bg-white py-1.5 shadow-kuat\"><li><a class=\"block border-b border-garis px-4 py-2.5 text-xs font-bold tracking-wide text-biru uppercase transition hover:bg-biru-muda\" href=\"/ppdb\">Ringkasan PPDB</a></li><li><a class=\"block px-4 py-2.5 text-sm transition hover:bg-biru-muda hover:text-biru font-medium text-teks\" href=\"/ppdb\">Ketentuan &amp; Jadwal</a></li><li><a class=\"block px-4 py-2.5 text-sm transition hover:bg-biru-muda hover:text-biru font-medium text-teks\" href=\"/ppdb/daftar\">Formulir Pendaftaran</a></li><li><a class=\"block px-4 py-2.5 text-sm transition hover:bg-biru-muda hover:text-biru font-medium text-teks\" href=\"/ppdb/cek\">Cek Status &amp; Hasil</a></li><li><a class=\"block px-4 py-2.5 text-sm transition hover:bg-biru-muda hover:text-biru font-medium text-teks\" href=\"/ppdb/ujian\">Tes Seleksi</a></li><li><a class=\"block px-4 py-2.5 text-sm transition hover:bg-biru-muda hover:text-biru font-medium text-teks\" href=\"/faq\">Tanya Jawab</a></li></ul></div>"
